mapper.select:
SELECT r.id, r.name, r.description, r.category_id, rc.name AS category_name, r.budget, r.duration_days, r.best_season, r.images, r.status, r.view_count, COUNT(rcoll.id) AS collection_count, r.create_time FROM travel_route r LEFT JOIN route_category rc ON r.category_id = rc.id LEFT JOIN route_collection rcoll ON r.id = rcoll.route_id AND rcoll.deleted = 0 WHERE r.deleted = 0
AND r.name LIKE CONCAT('%', #{query.name}, '%')
AND r.category_id = #{query.categoryId}
AND r.status = #{query.status}
GROUP BY r.id ORDER BY r.view_count DESC, r.create_time DESC
